302: fn reduce_tree<P: ReducePrecision, I: ReduceInstruction<P>>(
303:     inst: &I,
304:     shared_accumulator: &mut I::SharedAccumulator,
305:     accumulator: &mut Accumulator<P>,
306:     worker_index: usize,
307:     #[comptime] size: usize,
308: ) {
309:     if size.is_power_of_two() {
310:         let mut num_active_units = size.runtime();
311:         let mut jump = 1;
312:         while num_active_units > 1 {
313:             num_active_units /= 2;
314:             let destination = jump * 2 * worker_index;
315:             let origin = jump * (2 * worker_index + 1);
316:             if worker_index < num_active_units {
317:                 fuse_accumulator_inplace::<P, I>(inst, shared_accumulator, destination, origin);
318:             }
319:             jump *= 2;
320:             sync_cube();
321:         }
322:     } else {
323:         let mut num_remaining_items = size.runtime();
324:         let mut jump = 1;
325:         while num_remaining_items > 1 {
326:             let destination = jump * 2 * worker_index;
327:             let origin = jump * (2 * worker_index + 1);
328:             if worker_index < num_remaining_items / 2 {
329:                 fuse_accumulator_inplace::<P, I>(inst, shared_accumulator, destination, origin);
330:             }
331:             num_remaining_items = num_remaining_items.div_ceil(2);
332:             jump *= 2;
333:             sync_cube();
334:         }
335:     }
336:     sync_cube();
337: 
338:     let acc = I::SharedAccumulator::read(&*shared_accumulator, 0);
339:     I::fuse_accumulators(inst, accumulator, &acc);
340: }

