85: fn generate_blueprint(
86:     client: &Client,
87:     problem: ReduceProblem,
88:     settings: &ReduceVectorSettings,
89:     strategy: PlaneStrategy,
90: ) -> Result<(ReduceBlueprint, CubeDim, CubeCount), ReduceError> {
91:     if !support_plane(client) {
92:         return Err(ReduceError::PlanesUnavailable);
93:     }
94: 
95:     let properties = &client.properties().hardware;
96:     let plane_size = properties.plane_size_max;
97:     let working_planes = working_planes(settings, &problem);
98:     let working_units = working_planes * plane_size as usize;
99:     let plane_count = calculate_plane_count_per_cube(working_units, plane_size, properties);
100:     let working_cubes = working_planes.div_ceil(plane_count as usize);
101: 
102:     let cube_dim = CubeDim::new_2d(plane_size, plane_count);
103:     let (cube_count, cube_launched) = cube_count_spread_with_total(client, working_cubes);
104: 
105:     // The blueprint is comptime: every field forks a compiled kernel variant.
106:     // The problem sizes here are *raw* runtime lengths, while kernel selection
107:     // is cached per anchored autotune key: a variant choice derived from a
108:     // raw property (divisibility, exact launch fit) re-splits the anchored
109:     // bucket and keeps compiling "new" kernels long after a warmup covered
110:     // every key. The unchecked fast paths are therefore only taken when the
111:     // selection says raw shapes are their own keys
112:     // ([`ReduceStrategy::autotune_level`](crate::ReduceStrategy)); otherwise
113:     // the guarded variants (valid for every length sharing the key) run,
114:     // and the tuner benchmarks candidates with them, keeping the ranking
115:     // honest.
116:     let unchecked = settings.unchecked_fast_paths;
117:     let plane_idle = cube_launched * cube_dim.num_elems() as usize != working_units;
118:     let work_size = match settings.vectorization_mode {
119:         VectorizationMode::Parallel => problem.reduce_len / settings.vector_size_input,
120:         VectorizationMode::Perpendicular => problem.reduce_len,
121:     };
122:     // Out-of-range units come from the reduce-axis tail *and* from over-launched
123:     // (idle) planes; both need a bound check. When the input read has a write
124:     // side effect (fuse-on-read), that check must branch rather than mask: a
125:     // mask clamps the index to 0 and still performs the side-effecting read,
126:     // clobbering position 0.
127:     let tail_bounds = !(unchecked && work_size.is_multiple_of(plane_size as usize));
128:     let idle_possible = !unchecked || plane_idle;
129:     let bound_checks = if settings.fuse_on_read {
130:         match tail_bounds || idle_possible {
131:             true => BoundChecks::Branch,
132:             false => BoundChecks::None,
133:         }
134:     } else {
135:         match tail_bounds {
136:             true => BoundChecks::Mask,
137:             false => BoundChecks::None,
138:         }
139:     };
140: 
141:     let plane_idle = match !unchecked || plane_idle {
142:         true => match client
143:             .properties()
144:             .features
145:             .plane
146:             .contains(Plane::NonUniformControlFlow)
147:         {
148:             true => IdleMode::Terminate,
149:             false => IdleMode::Mask,
150:         },
151:         false => IdleMode::None,
152:     };
153: 
154:     let strategy_enum = if strategy.independent {
155:         PlaneMergeStrategy::Lazy
156:     } else {
157:         PlaneMergeStrategy::Eager
158:     };
159: 
160:     let blueprint = ReduceBlueprint {
161:         vectorization_mode: settings.vectorization_mode,
162:         global: GlobalReduceBlueprint::Plane(PlaneReduceBlueprint {
163:             plane_idle,
164:             bound_checks,
165:             plane_merge_strategy: strategy_enum,
166:             plane_dim_ceil: properties.plane_size_max != properties.plane_size_min,
167:         }),
168:     };
169: 
170:     Ok((blueprint, cube_dim, cube_count))

62: pub fn shared_sum(
63:     client: &Client,
64:     input: TensorBinding,
65:     output: TensorBinding,
66:     cube_count: u32,
67:     input_elem: ElemType,
68: ) -> Result<(), ReduceError> {
69:     // Check that the client supports atomic addition.
70:     if !client
71:         .properties()
72:         .atomic_type_usage(Type::atomic(input_elem))
73:         .contains(AtomicUsage::Add)
74:     {
75:         return Err(ReduceError::MissingAtomicAdd(input_elem));
76:     }
77: 
78:     let input_len = input.shape.iter().product::<usize>();
79:     let contiguous_buffer = input_len * input_elem.size() == input.handle.size_in_used() as usize
80:         && is_dense(&input.shape, &input.strides);
81: 
82:     // Compute the optimal vector size.
83:     let vector_size = if contiguous_buffer {
84:         client
85:             .io_optimized_vector_sizes(input_elem.size())
86:             .filter(|vector_size| input_len.is_multiple_of(*vector_size))
87:             .max()
88:             .unwrap_or(1)
89:     } else {
90:         tensor_vector_size_parallel(
91:             client.io_optimized_vector_sizes(input_elem.size()),
92:             &input.shape,
93:             &input.strides,
94:             input.shape.len() - 1,
95:         )
96:     };
97: 
98:     let address_type = input
99:         .required_address_type(input_elem.size())
100:         .max(output.required_address_type(input_elem.size()));
101: 
102:     // Sum is commutative so dimension order does not matter, but every buffer element must
103:     // occur exactly once. Equal logical and physical sizes alone do not rule out overlapping
104:     // windows or broadcasts that repeat some elements and leave others unused.
105:     let input_view = if contiguous_buffer {
106:         let layout = LinearViewLayoutLaunch::new();
107:         let buffer = unsafe { BufferArg::from_raw_parts_binding(input.handle, input_len) };
108:         LinearViewLaunch::new_array::<LinearViewLayout>(buffer, layout)
109:     } else {
110:         linear_view(input)
111:     };
112: 
113:     // Compute extra parameters. The tree reduce in the kernel requires a power-of-two unit
114:     // count, and the device caps how many units a cube may hold (e.g. the core count on the
115:     // CPU runtime), so clamp 256 to the largest power of two the device supports.
116:     let max_units = client.properties().hardware.max_units_per_cube;
117:     let cap = u32::min(256, max_units.max(1));
118:     let units = if cap.is_power_of_two() {
119:         cap
120:     } else {
121:         cap.next_power_of_two() >> 1
122:     };
123:     let dim_x = u32::min(32, units);
124:     let cube_dim = CubeDim::new_2d(dim_x, units / dim_x);
125:     let num_units = cube_count * cube_dim.num_elems();
126:     let num_vectors_per_unit = input_len.div_ceil(num_units as usize * vector_size);
127:     let cube_count = CubeCount::new_1d(cube_count);
128: 
129:     // Launch kernel
130:     unsafe {
131:         shared_sum_kernel::launch_unchecked(
132:             client,
133:             cube_count,
134:             cube_dim,
135:             address_type,
136:             vector_size,
137:             input_view,
138:             output.into_tensor_arg(),
139:             cube_dim.num_elems() as usize,
140:             num_vectors_per_unit,
141:             input_elem,
142:         )
143:     };
144: 
145:     Ok(())
146: }
