148: /// Whether the view visits consecutive elements exactly once, in any dimension order.
149: fn is_dense(shape: &[usize], strides: &[usize]) -> bool {
150:     let mut dims: Vec<_> = shape
151:         .iter()
152:         .zip(strides)
153:         .filter(|&(&dim, _)| dim > 1)
154:         .collect();
155:     dims.sort_unstable_by_key(|&(_, stride)| *stride);
156: 
157:     let mut expected = 1;
158:     for (&dim, &stride) in dims {
159:         if stride != expected {
160:             return false;
161:         }
162:         expected *= dim;
163:     }
164:     true
165: }
