168: fn shared_sum_kernel<T: Numeric, N: Size>(
169:     input: LinearView<'_, Vector<T, N>>,
170:     output: &mut Tensor<Atomic<T>>,
171:     #[comptime] shared_memory_size: usize,
172:     #[comptime] num_vectors_per_unit: usize,
173:     #[define(T)] _dtype: ElemType,
174: ) {
175:     let mut shared_memory = Shared::new_slice(shared_memory_size);
176:     shared_memory[UNIT_POS as usize] = Vector::empty().fill(T::from_int(0));
177: 
178:     // Each unit reduce `num_vectors_per_unit` vectors.
179:     let start = ABSOLUTE_POS * num_vectors_per_unit;
180:     let end = start + num_vectors_per_unit;
181: 
182:     // Prevent out-of-bound access
183:     let start = select(start < input.shape(), start, input.shape());
184:     let end = select(end < input.shape(), end, input.shape());
185: 
186:     // Each unit sum its vectors.
187:     for k in start..end {
188:         shared_memory[UNIT_POS as usize] += input.read(k);
189:     }
190: 
191:     // Sum all vectors within the shared_memory to a single vector.
192:     let vector = sum_shared_memory(&mut shared_memory);
193: 
194:     // Sum all the elements within the vector.
195:     let sum = RuntimeCell::<T>::new(T::from_int(0));
196:     #[unroll]
197:     for k in 0..N::value() {
198:         let update = vector.extract(k) + sum.read();
199:         sum.store(update);
200:     }
201: 
202:     // Add the sum for the current cube to the output.
203:     if UNIT_POS == 0 {
204:         output[0].fetch_add(sum.consume());
205:     }
206: }
