76:   static constexpr int BLOCK_Y = 1;
77:   static constexpr int CTA = 2;
78: 
79:   ReduceConfig(int element_size_bytes, int num_outputs, int num_inputs)
80:     : element_size_bytes(element_size_bytes)
81:     , num_inputs(num_inputs)
82:     , num_outputs(num_outputs) {}
83:   int element_size_bytes;
84:   int num_inputs;
85:   int num_outputs;
86:   int step_input = 1;
87:   int step_output = 1;
88:   int ctas_per_output = 1;
89:   int input_mult[3] = {0, 0, 0};
90:   int output_mult[2] = {0, 0};
91: 
92:   int block_width;
93:   int block_height;
94:   int num_threads;
95: 
96:   bool vectorize_input = false;
97:   int output_vec_size = 1;
