99:   template <typename T>
100:   void set_block_dimension(int64_t dim0, int64_t dim1) {
101:     const int max_num_threads = mnt_wrapper<T>::MAX_NUM_THREADS / output_vec_size;
102:     int dim0_pow2 = dim0 < max_num_threads ? static_cast<int>(last_pow2(dim0)) : max_num_threads;
103:     int dim1_pow2 = dim1 < max_num_threads ? static_cast<int>(last_pow2(dim1)) : max_num_threads;
104:     block_width = std::min(dim0_pow2, int(at::cuda::warp_size()));
105:     block_height = std::min(dim1_pow2, int(max_num_threads / block_width));
106:     block_width = std::min(dim0_pow2, int(max_num_threads / block_height));
107:     num_threads = block_width * block_height;
108:   }
109: 
110:   int split_input(int parallelism) {
111:     int step = step_input;
112:     step_input *= parallelism;
113:     return step;
114:   }
115: 
116:   int split_output(int parallelism) {
117:     int step = step_output;
118:     step_output *= parallelism;
119:     return step;
120:   }
121: 
122:   dim3 block() const {
123:     return dim3(block_width, block_height);
124:   }
125: 
126:   dim3 grid() const {
127:     return dim3(div_up(num_outputs / output_vec_size, step_output), ctas_per_output);
128:   }
