130:   C10_HOST_DEVICE bool should_block_x_reduce() const {
131:     return input_mult[BLOCK_X] != 0;
132:   }
133: 
134:   C10_HOST_DEVICE bool should_block_y_reduce() const {
135:     return input_mult[BLOCK_Y] != 0;
136:   }
137: 
138:   C10_HOST_DEVICE bool should_global_reduce() const {
139:     return input_mult[CTA] != 0;
140:   }
